
%% MATH 155 - Homework 2, Problem 2
% Laplacian Image Sharpening
% Norah Lynch
%
% Enhance image details using a discrete
% Laplacian sharpening operator.

clear; clc; close all;

%% Load image
I = imread('HW2Q2_original_image.jpg');

% Convert to grayscale if necessary
if size(I, 3) == 3
    Igray = rgb2gray(I);
else
    Igray = I;
end

Igray = uint8(Igray);

%% Convert to double precision
f = double(Igray);

%% Get image size
[M, N] = size(f);

%% Define discrete Laplacian mask
laplacianMask = [ 0  1  0;
                  1 -4  1;
                  0  1  0 ];

%% Define sharpening mask
% g = f - Laplacian(f)

sharpeningMask = [ 0 -1  0;
                  -1  5 -1;
                   0 -1  0 ];

%% Pad original image
% Replicate boundary pixels

Ipad = zeros(M+2, N+2);

% Copy original image into center
Ipad(2:M+1, 2:N+1) = f;

% Replicate top and bottom rows
Ipad(1, 2:N+1) = f(1, :);
Ipad(M+2, 2:N+1) = f(M, :);

% Replicate left and right columns
Ipad(2:M+1, 1) = f(:, 1);
Ipad(2:M+1, N+2) = f(:, N);

% Replicate four corners
Ipad(1, 1) = f(1, 1);
Ipad(1, N+2) = f(1, N);
Ipad(M+2, 1) = f(M, 1);
Ipad(M+2, N+2) = f(M, N);

%% Apply sharpening filter manually

g = zeros(M, N);

for i = 1:M
    for j = 1:N

        % Extract 3x3 neighborhood
        window = Ipad(i:i+2, j:j+2);

        % Multiply by sharpening mask and sum
        g(i,j) = sum(window .* sharpeningMask, 'all');

    end
end

%% Clip values to valid grayscale range
g(g < 0) = 0;
g(g > 255) = 255;

%% Convert back to uint8
g = uint8(g);

%% Display original and sharpened images

figure('Name', 'Laplacian Sharpening'); %[output:975709da]

subplot(1,2,1); %[output:975709da]
imshow(Igray); %[output:975709da]
title('Input Image: Q2.jpg'); %[output:975709da]

subplot(1,2,2); %[output:975709da]
imshow(g); %[output:975709da]
title('Output Image: g = f - Laplacian(f)'); %[output:975709da]

%% Save output image
imwrite(g, 'Q2_laplacian_sharpened.png');

%% Save comparison figure
exportgraphics(gcf, 'Q2_comparison.png'); %[output:975709da]

disp('Laplacian sharpening completed.'); %[output:0e4c9820]
disp('Output images saved successfully.'); %[output:1e494f84]


